type LogoProps = {
  className?: string;
};

/**
 * The sunny*r ambigram wordmark — reads identically rotated 180°.
 * The artwork (public/images/sunnyr-logo-outlined.svg, the mark ~1.86:1 in a
 * periwinkle outline, generated by docs/logo/build_logo.py) is one
 * picture, so `.logo-art` in globals.css owns it, and swaps in the heavier cut on
 * phones. Size it with a height utility on `className` (e.g. `h-14 w-auto`).
 */
export function Logo({ className = "" }: LogoProps) {
  return (
    <div role="img" aria-label="sunny*r" className={`logo ${className}`}>
      <span aria-hidden="true" className="logo-art" />
    </div>
  );
}
